    ['r1-t01', 'work-480b1f', 'MATH-500, plain prompt, one sample', 'right answers of 500', 'How many of the 500 MATH-500 problems the Olmo-3.1 RL-Zero-Math step-100 checkpoint answers right with the plain prompt, one sample at T 1.0 / top-p 1.0, graded by grader v3.', 418, 'result-fad48d', '2026-11-15T15:39:20', 'score: other MATH-500 418/500 tokens 4120 | RL step 100, plain, T 1.0 / top-p 1.0', [['run-01', 't01', 'reader-1', 423, 410, 436, -0.084, "Interim 405 of 478 (84.7 %) scaled to 500 is about 424; this is a new sample on a new box, so I use binomial noise around the step-400 plain 436 and the spec's 428."], ['run-01', 't01', 'reader-2', 421, 408, 433, 0.0775, 'Interim 405 of 478 (84.7 %) with the unfinished problems likely the long, harder ones; between base cue 410 and step-400 plain 436, spec predicted 428.'], ['run-02', 't01', 'reader-1', 420, 408, 432, 0.021, 'Partial 405/478 plus about 15 of the remaining 22 harder problems (base cue got 13 of them), with rerun noise because the full rerun is a new sample.'], ['run-02', 't01', 'reader-2', 418, 405, 431, -0.0215, 'Partial 405/478 plus ~13 of the 22 held-back (longer) problems, as the base cue got 13/22 on them, with ~7-problem rerun noise on a new box.'], ['run-02', 't01', 'f2-m01', 419, 410, 428, 0.3296, '405/478 plus ~13 of the 22 long problems that were cut, rerun noise ~6.'], ['run-02', 't01', 'f2-m03', 420, 411, 429, 0.2795, 'Step 100 already finishes like the cued base; 405/478 plus ~14 of 22.'], ['run-02', 't01', 'f2-m06', 421, 412, 430, 0.1959, 'Step 100 has part of the controller: 405/478 plus ~15 of 22.']]],
